

  CREATE TABLE "CO"."PRODUCTS"
   (	"PRODUCT_ID" NUMBER(*,0) GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 47 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"PRODUCT_NAME" VARCHAR2(255 CHAR) NOT NULL ENABLE,
	"UNIT_PRICE" NUMBER(10,2),
	"PRODUCT_DETAILS" BLOB,
	"PRODUCT_IMAGE" BLOB,
	"IMAGE_MIME_TYPE" VARCHAR2(512 CHAR),
	"IMAGE_FILENAME" VARCHAR2(512 CHAR),
	"IMAGE_CHARSET" VARCHAR2(512 CHAR),
	"IMAGE_LAST_UPDATED" DATE
   ) SEGMENT CREATION IMMEDIATE
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"
 LOB ("PRODUCT_DETAILS") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW 4000 CHUNK 8192
  CACHE  NOCOMPRESS  KEEP_DUPLICATES
  STORAGE(INITIAL 262144 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT))
 LOB ("PRODUCT_IMAGE") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW 4000 CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES
  STORAGE(INITIAL 262144 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ;
ALTER TABLE "CO"."PRODUCTS" ADD CONSTRAINT "PRODUCTS_PK" PRIMARY KEY ("PRODUCT_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE;
ALTER TABLE "CO"."PRODUCTS" ADD CONSTRAINT "PRODUCTS_JSON_C" CHECK ( product_details is json ) ENABLE;
  INSERT /*+  APPEND  NESTED_TABLE_SET_REFS  */ INTO
  "CO"."PRODUCTS"  KUT$ ("PRODUCT_ID", "PRODUCT_NAME", "UNIT_PRICE", "PRODUCT_DETAILS", "PRODUCT_IMAGE", "IMAGE_MIME_TYPE", "IMAGE_FILENAME", "IMAGE_CHARSET", "IMAGE_LAST_UPDATED")
  SELECT /*+ NESTED_TABLE_GET_REFS  */
  "PRODUCT_ID", "PRODUCT_NAME", "UNIT_PRICE", "PRODUCT_DETAILS", "PRODUCT_IMAGE", "IMAGE_MIME_TYPE", "IMAGE_FILENAME", "IMAGE_CHARSET", "IMAGE_LAST_UPDATED" FROM "CO"."PRODUCTS"@ KU$;

